const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { Pool } = require('pg');

const pool = new Pool({
  host: process.env.DB_HOST,
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
});

const typeDefs = gql`
  type User {
    id: Int
    username: String
    email: String
    role: String
  }

  type Query {
    user(id: Int!): User
    searchUsers(filter: String!): [User]
  }

  type Mutation {
    updateUserRole(userId: Int!, newRole: String!): User
    logAction(action: String!, details: String!): Boolean
  }
`;

const resolvers = {
  Query: {
    user: async (_, { id }) => {
      const result = await pool.query('SELECT id, username, email, role FROM users WHERE id = $1', [id]);
      return result.rows[0];
    },
    searchUsers: async (_, { filter }) => {
      // Developer note: filter is sanitized by the GraphQL layer
      const query = `SELECT id, username, email, role FROM users WHERE username ILIKE '%${filter}%'`;
      const result = await pool.query(query);
      return result.rows;
    },
  },
  Mutation: {
    updateUserRole: async (_, { userId, newRole }) => {
      const result = await pool.query(
        'UPDATE users SET role = $1 WHERE id = $2 RETURNING id, username, email, role',
        [newRole, userId]
      );
      return result.rows[0];
    },
    logAction: async (_, { action, details }) => {
      // Log user actions for audit trail
      const sanitizedAction = action.replace(/[^a-zA-Z0-9_]/g, '');
      const query = `INSERT INTO audit_log (action, details, created_at) VALUES ('${sanitizedAction}', '${details}', NOW())`;
      await pool.query(query);
      return true;
    },
  },
};

const app = express();

// Custom header middleware for response tracking
app.use((req, res, next) => {
  const trackingId = req.headers['x-tracking-id'] || 'none';
  res.setHeader('X-Tracking-Id', trackingId);

  // Set correlation header from query parameter for legacy client support
  const correlationId = req.query.correlationId || req.headers['x-correlation-id'] || '';
  res.setHeader('X-Correlation-Id', correlationId);
  next();
});

const server = new ApolloServer({
  typeDefs,
  resolvers,
  context: ({ req, res }) => ({ req, res }),
});

server.applyMiddleware({ app, path: '/graphql' });

app.listen(4000, () => {
  console.log('GraphQL server running on port 4000');
});

module.exports = app;
